import{_ as e,o as a,c as l,a2 as r}from"./chunks/framework.BQ1gajhD.js";const b=JSON.parse('{"title":"京郊周边游指南","description":"","frontmatter":{},"headers":[],"relativePath":"guide/suburban.md","filePath":"guide/suburban.md","lastUpdated":1787046740000}'),n={name:"guide/suburban.md"};function o(i,t,s,d,u,h){return a(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="京郊周边游指南" tabindex="-1">京郊周边游指南 <a class="header-anchor" href="#京郊周边游指南" aria-label="Permalink to &quot;京郊周边游指南&quot;">​</a></h1><blockquote><p>&quot;进山一天，换一种北京的打开方式。&quot;</p></blockquote><h2 id="长城三选一" tabindex="-1">长城三选一 <a class="header-anchor" href="#长城三选一" aria-label="Permalink to &quot;长城三选一&quot;">​</a></h2><p>北京长城资源丰富，小程序精选了三座各有性格的长城，按需选择：</p><table tabindex="0"><thead><tr><th style="text-align:left;">长城</th><th style="text-align:left;">特点</th><th style="text-align:left;">适合人群</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>水关</strong></td><td style="text-align:left;">唯一以&quot;水&quot;命名的关隘，跨河而过，人少清静</td><td style="text-align:left;">避开人潮、摄影爱好者</td></tr><tr><td style="text-align:left;"><strong>慕田峪</strong></td><td style="text-align:left;">植被茂密，游客相对少，秋季最美</td><td style="text-align:left;">想要更好体验感、摄影爱好者</td></tr><tr><td style="text-align:left;"><strong>司马台</strong></td><td style="text-align:left;">最险峻，与古北水镇相邻，可看夜景</td><td style="text-align:left;">体力好、追求野趣的深度玩家</td></tr></tbody></table><p>三座长城都建议<strong>早出发</strong>：水关长城可乘京张高铁至八达岭长城站后打车即达；慕田峪、司马台需换乘巴士或包车，旺季周末务必预留堵车时间。</p><h2 id="西郊一日-香山与植物园" tabindex="-1">西郊一日：香山与植物园 <a class="header-anchor" href="#西郊一日-香山与植物园" aria-label="Permalink to &quot;西郊一日：香山与植物园&quot;">​</a></h2><p>香山公园与北京植物园相邻，可合并一日游览：</p><ul><li><strong>10月底-11月中</strong>：香山红叶季，人多，建议工作日前往，缆车排队时间长</li><li><strong>春季</strong>：植物园郁金香、桃花盛开，比红叶季安静得多</li><li>地铁西郊线（香山站/植物园站）是唯一专线，旺季排队时间不短，可考虑打车到山脚</li></ul><h2 id="西郊工业风-首钢园" tabindex="-1">西郊工业风：首钢园 <a class="header-anchor" href="#西郊工业风-首钢园" aria-label="Permalink to &quot;西郊工业风：首钢园&quot;">​</a></h2><p>首钢园是近郊最特别的存在：冬奥大跳台「雪飞天」、高炉群与空中步道，工业废墟感十足。园区免费，地铁11号线可达，适合骑行、拍照，傍晚灯光亮起后更出片。</p><h2 id="京郊出行提示" tabindex="-1">京郊出行提示 <a class="header-anchor" href="#京郊出行提示" aria-label="Permalink to &quot;京郊出行提示&quot;">​</a></h2><ul><li>京藏高速延庆方向节假日拥堵严重，尽量避开节假日首尾两天</li><li>山区温差大，春秋进山带外套，夏末注意防晒</li><li>司马台长城与古北水镇建议安排2天1夜，晚间长城灯光与古镇夜景才是精华</li></ul>',13)])])}const c=e(n,[["render",o]]);export{b as __pageData,c as default};
